#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
using namespace std;

long long gcd_func(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

long long lcm_func(long long a, long long b) {
    return a / gcd_func(a, b) * b;
}

struct FractionStruct {
    long long num;
    long long den;
};

FractionStruct absolute_value(const FractionStruct& f) {
    return {abs(f.num), f.den};
}

int compare_fraction(const FractionStruct& a, const FractionStruct& b) {
    long long l = lcm_func(a.den, b.den);
    long long na = a.num * (l / a.den);
    long long nb = b.num * (l / b.den);
    if (na == nb) return 0;
    return (na < nb) ? -1 : 1;
}

FractionStruct subtract_fraction(const FractionStruct& a, const FractionStruct& b) {
    long long l = lcm_func(a.den, b.den);
    long long na = a.num * (l / a.den);
    long long nb = b.num * (l / b.den);
    long long res_num = na - nb;
    long long g = gcd_func(abs(res_num), l);
    return {res_num / g, l / g};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long x, y, n;
    cin >> x >> y >> n;
    long long g = gcd_func(x, y);
    x /= g; y /= g;
    FractionStruct xy = {x, y};
    FractionStruct min_diff = {1000000000000LL, 1};
    FractionStruct min_val = {0, 0};
    for (long long b = 1; b <= n; ++b) {
        long long l = 0, r = 1000000;
        double maxv = (double)x / y + (double)min_diff.num / min_diff.den + 2;
        maxv *= b;
        r = (long long)maxv;
        while (l <= r) {
            long long mid = l + (r - l) / 2;
            FractionStruct candidate = {mid, b};
            FractionStruct diff = absolute_value(subtract_fraction(xy, candidate));
            int cmp = compare_fraction(diff, min_diff);
            if (cmp == 0) {
                if (candidate.den < min_val.den)
                    min_val = candidate;
                else if (candidate.den == min_val.den && candidate.num < min_val.num)
                    min_val = candidate;
            } else if (cmp < 0) {
                min_diff = diff;
                min_val = candidate;
            }
            if (compare_fraction(candidate, xy) < 0)
                l = mid + 1;
            else
                r = mid - 1;
        }
    }
    cout << min_val.num << "/" << min_val.den;
    return 0;
}
