import java.util.Scanner;

public class Main {
    static long gcdFunc(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    static long lcmFunc(long a, long b) {
        return a / gcdFunc(a, b) * b;
    }

    static class Fraction {
        long num;
        long den;

        Fraction(long num, long den) {
            this.num = num;
            this.den = den;
        }
    }

    static Fraction absoluteValue(Fraction f) {
        return new Fraction(Math.abs(f.num), f.den);
    }

    static int compareFraction(Fraction a, Fraction b) {
        long l = lcmFunc(a.den, b.den);
        long na = a.num * (l / a.den);
        long nb = b.num * (l / b.den);
        if (na == nb) return 0;
        return (na < nb) ? -1 : 1;
    }

    static Fraction subtractFraction(Fraction a, Fraction b) {
        long l = lcmFunc(a.den, b.den);
        long na = a.num * (l / a.den);
        long nb = b.num * (l / b.den);
        long resNum = na - nb;
        long g = gcdFunc(Math.abs(resNum), l);
        return new Fraction(resNum / g, l / g);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long g = gcdFunc(x, y);
        x /= g;
        y /= g;
        Fraction xy = new Fraction(x, y);
        Fraction minDiff = new Fraction(1000000000000L, 1);
        Fraction minVal = new Fraction(0, 0);

        for (long b = 1; b <= n; b++) {
            long l = 0, r = 1000000;
            double maxv = (double) x / y + (double) minDiff.num / minDiff.den + 2;
            maxv *= b;
            r = (long) maxv;

            while (l <= r) {
                long mid = l + (r - l) / 2;
                Fraction candidate = new Fraction(mid, b);
                Fraction diff = absoluteValue(subtractFraction(xy, candidate));
                int cmp = compareFraction(diff, minDiff);
                if (cmp == 0) {
                    if (candidate.den < minVal.den)
                        minVal = candidate;
                    else if (candidate.den == minVal.den && candidate.num < minVal.num)
                        minVal = candidate;
                } else if (cmp < 0) {
                    minDiff = diff;
                    minVal = candidate;
                }
                if (compareFraction(candidate, xy) < 0)
                    l = mid + 1;
                else
                    r = mid - 1;
            }
        }
        System.out.println(minVal.num + "/" + minVal.den);
        sc.close();
    }
}
